{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Reject. Our baseline is **25% / $6m**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Require **$5,000 de minimis**, **$50,000 aggregate basket**, and a **tipping/first-dollar basket** once exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Reject. Require **24 months from Completion**. The 18-month fallback is not authorised."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Capacity, authority, title and ownership claims need a separate regime: **100% price cap**, survival for **at least six years**"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "fraud, wilful concealment and deliberate misconduct outside every limitation and remedy exclusion."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject deemed/whole-data-room/public-record disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete. It is both a blanket knowledge exclusion and an impermissible constructive-knowledge standard."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Completion must require an **effective consent** and evidence that **every condition to it has been satisfied**."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require current payout information, **direct repayment out of Completion funds**, and effective releases of all related security at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "The current funds flow cannot silently omit them. Obtain quantified on-costs and confirmation of payment responsibility."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require a broader, standalone IP/payment/ownership indemnity covering non-payment, failure of transfer, infringement/ownership exposure, losses and enforcement"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Preserve logs and relevant evidence, require a documented investigation and regular updates, and obtain control/cooperation rights on response."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Do not accept the characterisation without evidence."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "preserve separate Tax, IP, payment and covenant treatment."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require independent evidence of ownership, authority and absence of Encumbrances"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Preserve separate drafting and negotiated liability treatment; do not assume unlimited liability or any agreed resolution."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

